_ACTIONS = json.loads(_SOURCE_ACTIONS_JSON)

def reset_agent():
    return None

def agent(obs, configuration=None):
    step = int(obs.get("step", 0) or 0)
    player = int(obs.get("player", 0) or 0)
    hands = len(obs["farms"][player].get("hands", []) or [])
    if not 0 <= step < len(_ACTIONS):
        return {"farmer": ["PASS"], "hands": [["PASS"] for _ in range(hands)], "market": []}
    action = deepcopy(_ACTIONS[step])
    scheduled = list(action.get("hands", []) or [])
    action["hands"] = (scheduled + [["PASS"]] * hands)[:hands]
    return action
